#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *storage;
    size_t capacity;     /* max bytes (storage length) */
    size_t size;         /* currently stored bytes      */
    size_t head;         /* next write index           */
    size_t tail;         /* next read  index           */
};

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->storage = calloc(capacity, sizeof(uint8_t));
    if (!rb->storage) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->size = 0;
    rb->head = 0;
    rb->tail = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->storage);
    free(rb);
}

static void advance(ringbuf_t *rb, size_t *idx, size_t steps)
{
    *idx = (*idx + steps) % rb->capacity;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    size_t avail = rb->capacity - rb->size;
    if (avail == 0)
        return 0;

    size_t n = len < avail ? len : avail;

    /* Try to fit in one contiguous chunk from head */
    size_t first_chunk = rb->capacity - rb->head; /* bytes from head to end */
    size_t copy1 = n < first_chunk ? n : first_chunk;

    memcpy(rb->storage + rb->head, data, copy1);
    rb->head += copy1;
    if (rb->head >= rb->capacity)
        rb->head -= rb->capacity;

    /* Wrap around */
    size_t copy2 = n - copy1;
    if (copy2 > 0) {
        memcpy(rb->storage + rb->head, data + copy1, copy2);
        rb->head += copy2;
    }

    rb->size += n;
    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    if (rb->size == 0)
        return 0;

    size_t n = len < rb->size ? len : rb->size;

    size_t first_chunk = rb->capacity - rb->tail;
    size_t copy1 = n < first_chunk ? n : first_chunk;

    memcpy(out, rb->storage + rb->tail, copy1);
    rb->tail += copy1;
    if (rb->tail >= rb->capacity)
        rb->tail -= rb->capacity;

    size_t copy2 = n - copy1;
    if (copy2 > 0) {
        memcpy(out + copy1, rb->storage + rb->tail, copy2);
        rb->tail += copy2;
    }

    rb->size -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    if (rb->size == 0)
        return 0;

    size_t n = len < rb->size ? len : rb->size;
    size_t pos = rb->tail; /* don't advance tail */

    size_t first_chunk = rb->capacity - pos;
    size_t copy1 = n < first_chunk ? n : first_chunk;

    memcpy(out, rb->storage + pos, copy1);

    size_t copy2 = n - copy1;
    if (copy2 > 0) {
        memcpy(out + copy1, rb->storage, copy2);
    }

    return n;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->size;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->size = 0;
    rb->head = 0;
    rb->tail = 0;
}

#include <stdio.h>
#include <string.h>
#include "ringbuf.h"

int main(void)
{
    /* NULL-safe operations */
    if (rb_size(NULL) != 0) return 1;
    if (rb_capacity(NULL) != 0) return 2;
    rb_destroy(NULL);  /* must not crash */
    rb_clear(NULL);    /* must not crash */

    /* Create / capacity */
    ringbuf_t *rb = rb_create(8);
    if (!rb) return 3;
    if (rb_capacity(rb) != 8) return 4;
    if (rb_size(rb) != 0) return 5;

    /* Write & read round-trip */
    unsigned char msg[] = "Hello, ring!";
    size_t w = rb_write(rb, msg, sizeof(msg) - 1);
    if (w != 12) return 6;
    if (rb_size(rb) != 12) return 7;

    /* Wrap-around write */
    unsigned char more[] = "AABBCCDDEEFF"; /* another 12 bytes */
    w = rb_write(rb, more, sizeof(more) - 1);
    if (w != 4) return 8;   /* only 4 fit in remaining space */

    /* Read exactly what was written */
    unsigned char buf[20];
    size_t r = rb_read(rb, buf, sizeof(buf));
    if (r != 16) return 9;
    if (memcmp(buf, msg, sizeof(msg) - 1) != 0) return 10;
    if (memcmp(buf + 12, more, 4) != 0) return 11;

    /* Continue reading remaining */
    r = rb_read(rb, buf + 16, 4);
    if (r != 8) return 12;

    /* Now fully drained */
    if (rb_size(rb) != 0) return 13;
    r = rb_read(rb, buf, 4);
    if (r != 0) return 14;

    /* Clear test */
    for (int i = 0; i < 64; i++)
        (void)rb_write(rb, &i, sizeof(i));
    rb_clear(rb);
    if (rb_size(rb) != 0) return 15;
    if (rb_capacity(rb) != 8) return 16;

    /* Peek without consuming */
    uint8_t p1[] = {0x01, 0x02};
    rb_write(rb, p1, 2);
    uint8_t peek[4];
    r = rb_peek(rb, peek, sizeof(peek));
    if (r != 2) return 17;
    if (peek[0] != 0x01 || peek[1] != 0x02) return 18;
    r = rb_read(rb, peek, 4);
    if (r != 2) return 19;   /* still only 2 bytes available */

    /* Invalid create */
    ringbuf_t *bad = rb_create(0);
    if (bad) return 20;

    /* NULL write/read/peek */
    if (rb_write(NULL, p1, 2) != 0) return 21;
    if (rb_read(NULL, peek, 4) != 0) return 22;
    if (rb_peek(NULL, peek, 4) != 0) return 23;

    rb_destroy(rb);

    printf("All tests passed\n");
    return 0;
}

